BEGIN;
INSERT INTO private.team_member_permissions(membership_id,permission_code)SELECT m.id,p FROM public.memberships m CROSS JOIN unnest(ARRAY['requests.read','requests.update'])p WHERE m.id IN('00000000-0000-4000-b000-000000000732','00000000-0000-4000-b000-000000000733') ON CONFLICT DO NOTHING;
INSERT INTO private.team_member_permissions(membership_id,permission_code)VALUES('00000000-0000-4000-b000-000000000732','requests.level2') ON CONFLICT DO NOTHING;
CREATE TEMP TABLE routing_requests(level integer,id uuid);
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000731","session_id":"00000000-0000-4000-c000-000000000731"}';
SELECT public.service_categories_command('00000000-0000-4000-e000-000000000731',jsonb_build_object('kind','create','name','Routing '||l,'execution_level',l,'reason','Classificação local de teste'),gen_random_uuid()) FROM generate_series(1,3)l;
INSERT INTO private.document_presence(office_id,membership_id,session_id,status,capacity,last_seen)SELECT m.office_id,m.id,s.id,'available',10,clock_timestamp() FROM public.memberships m JOIN auth.sessions s ON s.user_id=m.user_id WHERE m.office_id='00000000-0000-4000-e000-000000000731' AND m.role_code<>'client' AND m.id IN('00000000-0000-4000-b000-000000000731','00000000-0000-4000-b000-000000000732','00000000-0000-4000-b000-000000000733') ON CONFLICT(office_id,membership_id)DO UPDATE SET status='available',capacity=10,last_seen=clock_timestamp();
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000734","session_id":"00000000-0000-4000-c000-000000000734"}';
SELECT test.expect_error($q$SELECT public.request_create('00000000-0000-4000-e000-000000000731','{"origin":"portal","title":"Sem categoria","message":"Tentativa fora do formulário"}',gen_random_uuid(),gen_random_uuid())$q$,'PT422','routing: legacy public RPC cannot bypass mandatory category');
SELECT test.assert_true(public.request_create('00000000-0000-4000-e000-000000000731',jsonb_build_object('origin','portal','title','Categoria por RPC legada','message','Abertura categorizada','category_id',(SELECT id FROM private.service_categories WHERE office_id='00000000-0000-4000-e000-000000000731' AND name='Routing 3')),gen_random_uuid(),gen_random_uuid())->>'category_name'='Routing 3','routing: legacy public RPC with category delegates to canonical workflow');
INSERT INTO routing_requests SELECT l,(public.categorized_request_create('00000000-0000-4000-e000-000000000731',jsonb_build_object('origin','portal','title','Categoria nível '||l,'message','Solicitação própria','category_id',(SELECT id FROM private.service_categories WHERE office_id='00000000-0000-4000-e000-000000000731' AND name='Routing '||l)),gen_random_uuid())->>'id')::uuid FROM generate_series(1,3)l;
SELECT test.assert_true(r.assignee_id IS NOT NULL AND private.request_execution_allowed(r,m),'routing: online category level '||t.level||' reaches enabled staff') FROM routing_requests t JOIN public.requests r ON r.id=t.id LEFT JOIN public.memberships m ON m.id=r.assignee_id;
SELECT test.assert_true((SELECT r.assignee_id='00000000-0000-4000-b000-000000000731' FROM routing_requests t JOIN public.requests r ON r.id=t.id WHERE t.level=1),'routing: only level1-enabled owner receives restricted request');
ROLLBACK;
